    var cellName = (cell && cell.name) || 'YOUR CELL';
    if (!cellId) return;
    if (dismissed(kind, cellId)) return;
    var host = null;
    try { host = document.getElementById('pf-cells'); } catch (e) {}
    if (!host) return;
