    c.sort(function(a,b){
      var d=Number(b.propaganda_score)-Number(a.propaganda_score); if(d) return d;
      var f=(Number(b.followers_total)||0)-(Number(a.followers_total)||0); if(f) return f;
      return String(a.name||"").localeCompare(String(b.name||""));
    });
    return c.slice(0,3);
